import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const STATES = new Set(['pending', 'succeeded', 'failed']);

const isPlainObject = value =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const isId = value => typeof value === 'string' && value.length !== 0;

// Code-unit ordering, matching the `<`/`>` operators (not locale collation).
const byCodeUnit = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

function validate(spec) {
  if (!Array.isArray(spec)) throw new Error('spec must be an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (!isPlainObject(job)) throw new Error('each job must be an object');
    if (!isId(job.id)) throw new Error('each job needs a nonempty string id');
    if (jobs.has(job.id)) throw new Error(`duplicate job id: ${job.id}`);
    if (!STATES.has(job.state)) throw new Error(`invalid state for job: ${job.id}`);
    if (!Array.isArray(job.deps)) throw new Error(`deps must be an array: ${job.id}`);
    const deps = new Set();
    for (const dep of job.deps) {
      if (!isId(dep)) throw new Error(`deps must be nonempty strings: ${job.id}`);
      if (deps.has(dep)) throw new Error(`duplicate dependency ${dep} in job ${job.id}`);
      deps.add(dep);
    }
    jobs.set(job.id, { id: job.id, state: job.state, deps: [...deps] });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error(`unknown dependency ${dep} in job ${job.id}`);
    }
  }
  return jobs;
}

// Kahn's algorithm over the whole graph: repeatedly take the lexically
// smallest currently zero-indegree id, then update its children before
// choosing again.
function topoSort(jobs) {
  const indegree = new Map();
  const children = new Map();
  for (const id of jobs.keys()) {
    indegree.set(id, 0);
    children.set(id, []);
  }
  for (const job of jobs.values()) {
    indegree.set(job.id, job.deps.length);
    for (const dep of job.deps) children.get(dep).push(job.id);
  }
  const available = [...jobs.keys()].filter(id => indegree.get(id) === 0).sort(byCodeUnit);
  const order = [];
  while (available.length !== 0) {
    const id = available.shift();
    order.push(id);
    for (const child of children.get(id)) {
      const remaining = indegree.get(child) - 1;
      indegree.set(child, remaining);
      if (remaining === 0) {
        // Keep `available` sorted so the next pick is the smallest id that is
        // ready right now, rather than the smallest of a whole wave.
        let lo = 0;
        let hi = available.length;
        while (lo < hi) {
          const mid = (lo + hi) >> 1;
          if (available[mid] < child) lo = mid + 1;
          else hi = mid;
        }
        available.splice(lo, 0, child);
      }
    }
  }
  if (order.length !== jobs.size) throw new Error('dependency cycle detected');
  return order;
}

function failedAncestors(jobs, id) {
  const causes = new Set();
  const seen = new Set();
  const stack = [...jobs.get(id).deps];
  while (stack.length !== 0) {
    const current = stack.pop();
    if (seen.has(current)) continue;
    seen.add(current);
    const job = jobs.get(current);
    if (job.state === 'failed') causes.add(current);
    // Ancestry survives succeeded/failed intermediates, so always recurse.
    for (const dep of job.deps) stack.push(dep);
  }
  return causes;
}

export function planJobs(spec) {
  const jobs = validate(spec);
  const fullOrder = topoSort(jobs);

  const blocked = [];
  const blockedIds = new Set();
  for (const job of jobs.values()) {
    if (job.state !== 'pending') continue;
    const causes = failedAncestors(jobs, job.id);
    if (causes.size === 0) continue;
    blockedIds.add(job.id);
    blocked.push({ id: job.id, causes: [...causes].sort(byCodeUnit) });
  }
  blocked.sort((a, b) => byCodeUnit(a.id, b.id));

  const order = fullOrder.filter(
    id => jobs.get(id).state === 'pending' && !blockedIds.has(id),
  );

  const ready = order
    .filter(id => jobs.get(id).deps.every(dep => jobs.get(dep).state === 'succeeded'))
    .sort(byCodeUnit);

  return { order, ready, blocked };
}

function main(argv) {
  if (argv.length !== 1) throw new Error('usage: node job-plan.js SPECFILE');
  const text = readFileSync(argv[0], 'utf8');
  return planJobs(JSON.parse(text));
}

const invokedPath = process.argv[1];
if (invokedPath && import.meta.url === pathToFileURL(invokedPath).href) {
  try {
    process.stdout.write(JSON.stringify(main(process.argv.slice(2))) + '\n');
  } catch (error) {
    process.stderr.write(`${error && error.message ? error.message : error}\n`);
    process.exit(2);
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });
const CLI = fileURLToPath(new URL('../job-plan.js', import.meta.url));

test('kahn picks the smallest currently-available id, not whole waves', () => {
  // b unlocks a; a is smaller than c/z but only becomes available after b.
  const plan = planJobs([job('z'), job('c'), job('b'), job('a', ['b'])]);
  assert.deepEqual(plan.order, ['b', 'a', 'c', 'z']);
});

test('ordering is code-unit, not locale collation', () => {
  const plan = planJobs([job('a'), job('B'), job('ä'), job('Z')]);
  assert.deepEqual(plan.order, ['B', 'Z', 'a', 'ä']);
});

test('causes traverse through succeeded and failed intermediates', () => {
  const plan = planJobs([
    job('f1', [], 'failed'),
    job('f2', [], 'failed'),
    job('mid', ['f1'], 'succeeded'),
    job('other', ['f2'], 'failed'),
    job('leaf', ['mid', 'other']),
  ]);
  assert.deepEqual(plan, {
    order: [],
    ready: [],
    blocked: [{ id: 'leaf', causes: ['f1', 'f2', 'other'] }],
  });
});

test('ready describes current state, not a simulated future', () => {
  const plan = planJobs([job('a', [], 'succeeded'), job('b', ['a']), job('c', ['b'])]);
  assert.deepEqual(plan, { order: ['b', 'c'], ready: ['b'], blocked: [] });
});

test('__proto__ and constructor are ordinary ids', () => {
  const plan = planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]);
  assert.deepEqual(plan, {
    order: [],
    ready: [],
    blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('self dependency is a cycle', () => {
  assert.throws(() => planJobs([job('a', ['a'])]));
});

test('cycles among completed jobs still throw', () => {
  assert.throws(() =>
    planJobs([job('a', ['b'], 'succeeded'), job('b', ['a'], 'failed'), job('c')]),
  );
});

test('malformed specs throw', () => {
  assert.throws(() => planJobs([job('a'), job('a')]), /duplicate/);
  assert.throws(() => planJobs([job('a', ['b', 'b']), job('b')]), /duplicate/);
  assert.throws(() => planJobs([job('', [])]));
  assert.throws(() => planJobs([job('a', [], 'PENDING')]));
  assert.throws(() => planJobs([job('a', [1])]));
  assert.throws(() => planJobs([{ id: 'a', state: 'pending' }]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs('nope'));
});

test('input is not mutated and unknown fields are ignored', () => {
  const spec = [{ id: 'a', deps: [], state: 'pending', note: 'x' }];
  const snapshot = JSON.parse(JSON.stringify(spec));
  planJobs(spec);
  assert.deepEqual(spec, snapshot);
});

test('CLI prints the plan and exits 0', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'jobplan-'));
  const file = path.join(dir, 'spec.json');
  writeFileSync(file, JSON.stringify([job('build', ['fetch']), job('fetch')]), 'utf8');
  const out = execFileSync(process.execPath, [CLI, file], { encoding: 'utf8' });
  assert.equal(out, JSON.stringify({ order: ['fetch', 'build'], ready: ['fetch'], blocked: [] }) + '\n');
});

test('CLI failures produce exit 2, stderr, and no stdout', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'jobplan-'));
  const bad = path.join(dir, 'bad.json');
  writeFileSync(bad, '{oops', 'utf8');
  const cycle = path.join(dir, 'cycle.json');
  writeFileSync(cycle, JSON.stringify([job('a', ['a'])]), 'utf8');

  for (const args of [[], [bad], [cycle], [path.join(dir, 'missing.json')], [bad, bad]]) {
    const res = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
    assert.equal(res.status, 2, `args: ${args.join(' ')}`);
    assert.equal(res.stdout, '');
    assert.ok(res.stderr.length > 0);
  }
});

test('importing the module does not run the CLI', () => {
  const res = spawnSync(process.execPath, ['--input-type=module', '-e', `import('${pathToJsonUrl(CLI)}')`], {
    encoding: 'utf8',
  });
  assert.equal(res.status, 0);
  assert.equal(res.stdout, '');
});

function pathToJsonUrl(p) {
  return new URL(`file://${p}`).href;
}

